-- Older installations do not have the territory images in their local registry.
alter table game.participants drop constraint participants_question_format_check;
alter table game.participants add constraint participants_question_format_check
 check(question_format in (1,2,3,4,5));

do $compatibility$
declare
 rpc text:=pg_get_functiondef('public.geoduel(text,jsonb)'::regprocedure);
 old_format text:=$fmt$case payload->>'questionFormat' when '4' then 4$fmt$;
 old_germany_guard text:=$fmt$not in ('3','4')$fmt$;
 selection_start text:=$fmt$if exists(select 1 from game.participants p where p.room_id=r and p.question_format<2) then$fmt$;
begin
 if strpos(rpc,old_format)=0 or strpos(rpc,old_germany_guard)=0 or strpos(rpc,selection_start)=0 then
  raise exception 'Unexpected GeoDuel question format';
 end if;
 rpc:=replace(rpc,old_format,replace(old_format,'when ''4''','when ''5'' then 5 when ''4'''));
 rpc:=replace(rpc,old_germany_guard,$fmt$not in ('3','4','5')$fmt$);
 -- This runs after the existing legacy-format exclusions and before planning.
 if strpos(rpc,'chosen:=game.pick_duel_flag(d,r,unsupported_questions);')=0 then
  raise exception 'Unexpected GeoDuel flag selection';
 end if;
 rpc:=replace(rpc,'chosen:=game.pick_duel_flag(d,r,unsupported_questions);',$fmt$
  chosen:=game.pick_duel_flag(d,r,unsupported_questions ||
   case when exists(select 1 from game.participants p where p.room_id=r and p.question_format<5)
    then array(select id from game.questions where id like 'flag-territory-v1-%' and enabled)
    else '{}'::text[] end);$fmt$);
 execute rpc;
end
$compatibility$;

insert into game.questions(id,category,difficulty,prompt,options,correct,explanation,media,provenance,enabled)
